CREATE TABLE capability_publishers (id TEXT NOT NULL, key_id TEXT NOT NULL, display_name TEXT NOT NULL, public_key_pem TEXT NOT NULL, tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE, allowed_package_types TEXT NOT NULL DEFAULT '[]', revoked_at INTEGER, created_at INTEGER, PRIMARY KEY(id));
CREATE UNIQUE INDEX capability_publishers_key_uq ON capability_publishers(id,key_id);
CREATE INDEX capability_publishers_scope_idx ON capability_publishers(tenant_id,workspace_id);
CREATE TABLE capability_packages (id TEXT PRIMARY KEY NOT NULL, package_id TEXT NOT NULL, version TEXT NOT NULL, package_type TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', publisher_id TEXT NOT NULL, publisher_key_id TEXT NOT NULL, manifest TEXT NOT NULL, manifest_hash TEXT NOT NULL, package_hash TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'quarantined', inspection TEXT NOT NULL DEFAULT '{}', tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE, owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, previous_version_id TEXT REFERENCES capability_packages(id) ON DELETE SET NULL, imported_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX capability_packages_version_scope_uq ON capability_packages(package_id,version,tenant_id,workspace_id);
CREATE INDEX capability_packages_scope_idx ON capability_packages(tenant_id,workspace_id);
CREATE INDEX capability_packages_state_idx ON capability_packages(state);
CREATE TABLE capability_evidence (id TEXT PRIMARY KEY NOT NULL, capability_package_id TEXT NOT NULL REFERENCES capability_packages(id) ON DELETE CASCADE, kind TEXT NOT NULL, status TEXT NOT NULL, hash TEXT NOT NULL, environment TEXT NOT NULL, independent INTEGER NOT NULL DEFAULT 0, expires_at INTEGER, created_at INTEGER);
CREATE INDEX capability_evidence_package_idx ON capability_evidence(capability_package_id);
CREATE INDEX capability_evidence_status_idx ON capability_evidence(status);
CREATE TABLE capability_installations (id TEXT PRIMARY KEY NOT NULL, capability_package_id TEXT NOT NULL REFERENCES capability_packages(id) ON DELETE CASCADE, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, state TEXT NOT NULL DEFAULT 'installed', permissions_approved INTEGER NOT NULL DEFAULT 0, activated_at INTEGER, deactivated_at INTEGER, installed_at INTEGER NOT NULL, reason TEXT);
CREATE UNIQUE INDEX capability_installations_scope_uq ON capability_installations(capability_package_id,tenant_id,workspace_id);
CREATE INDEX capability_installations_scope_idx ON capability_installations(tenant_id,workspace_id);
CREATE TABLE capability_candidates (id TEXT PRIMARY KEY NOT NULL, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, package_type TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'quarantined', reuse_decision TEXT NOT NULL, specification_hash TEXT NOT NULL, candidate_hash TEXT NOT NULL, candidate TEXT NOT NULL, created_at INTEGER, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX capability_candidates_hash_scope_uq ON capability_candidates(candidate_hash,tenant_id,workspace_id);
CREATE INDEX capability_candidates_scope_idx ON capability_candidates(tenant_id,workspace_id);
CREATE INDEX capability_candidates_state_idx ON capability_candidates(state);
CREATE TABLE compiled_missions (id TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL DEFAULT 1, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, intent TEXT NOT NULL, plan TEXT NOT NULL, semantic_diff TEXT NOT NULL DEFAULT '[]', findings TEXT NOT NULL DEFAULT '[]', gaps TEXT NOT NULL DEFAULT '[]', mission_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', created_at INTEGER, approved_at INTEGER);
CREATE UNIQUE INDEX compiled_missions_hash_scope_uq ON compiled_missions(mission_hash,tenant_id,workspace_id);
CREATE INDEX compiled_missions_scope_idx ON compiled_missions(tenant_id,workspace_id);
CREATE TABLE improvement_candidates (id TEXT PRIMARY KEY NOT NULL, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, proposal TEXT NOT NULL, builder_id TEXT NOT NULL, verifier_id TEXT, stage TEXT NOT NULL, patch_hash TEXT, update_candidate_hash TEXT, evidence TEXT NOT NULL DEFAULT '{}', created_at INTEGER, updated_at INTEGER NOT NULL);
CREATE INDEX improvement_candidates_scope_idx ON improvement_candidates(tenant_id,workspace_id);
CREATE INDEX improvement_candidates_stage_idx ON improvement_candidates(stage);
CREATE TABLE mission_team_handoffs (id TEXT PRIMARY KEY NOT NULL, team_id TEXT NOT NULL, mission_hash TEXT NOT NULL, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, sender_id TEXT NOT NULL, receiver_id TEXT NOT NULL, sender_role TEXT NOT NULL, receiver_role TEXT NOT NULL, payload TEXT NOT NULL, signature TEXT NOT NULL, sequence INTEGER NOT NULL, consumed_at INTEGER, created_at INTEGER);
CREATE INDEX mission_team_handoffs_mission_idx ON mission_team_handoffs(mission_hash);
CREATE UNIQUE INDEX mission_team_handoffs_sequence_uq ON mission_team_handoffs(team_id,sequence);
